        id: 'sh' + (i+1), name: m.name, brand: m.brand, category:'second-hand-mobiles', type:'phone',
        price, mrp: m.base, stock: 1 + (i % 4), rating: (4 + (i % 10) / 10).toFixed(1) * 1, reviews: 5 + (i % 20),
